import React, { useState, useEffect } from 'react';
import { Search, Plus, Menu, Heart, MessageCircle, Share, Bookmark, ChevronLeft, ChevronRight } from 'lucide-react';
import SwipeableContainer from './SwipeableContainer';
import './MainFeed.css';

const sampleData = {
  posts: [
    {
      id: 1,
      author: '山田花子',
